import * as THREE from 'three';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {refineSurfaceMaterials100} from './visual-quality100.js?v=185';
let bytes;
export async function repairTools139(){bytes||=(async()=>{const r=await fetch('./models/herramientas139/herramientas139.glb.gz?v=139');if(!r.ok)throw Error('Herramientas Blender '+r.status);return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();})().catch(e=>{bytes=null;throw e;});const root=(await new GLTFLoader().parseAsync((await bytes).slice(0),'')).scene,result={};refineSurfaceMaterials100(root);root.updateMatrixWorld(true);for(const id of ['screwdriver','wrench','meter','brush']){const g=root.getObjectByName('tool139_'+id);if(!g||!g.userData.tip139)throw Error('Herramienta incompleta '+id);g.removeFromParent();const inv=g.matrixWorld.clone().invert(),bins=new Map(),old=[];g.traverse(o=>{if(!o.isMesh)return;const list=bins.get(o.material)||[];list.push(o.geometry.clone().applyMatrix4(inv.clone().multiply(o.matrixWorld)));bins.set(o.material,list);old.push(o);});for(const o of old){o.removeFromParent();o.geometry.dispose();}for(const[m,gs]of bins){const geometry=mergeGeometries(gs,false);gs.forEach(g=>g.dispose());if(!geometry)throw Error('Mallas incompatibles '+id);const mesh=new THREE.Mesh(geometry,m);mesh.name='Herramienta116_'+id;mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh);}result[id]=g;}return result;}
export function disposeTools139(tools){const gs=new Set(),ms=new Set();for(const g of Object.values(tools))g.traverse(o=>{if(o.geometry)gs.add(o.geometry);if(o.material)ms.add(o.material);});for(const g of gs)g.dispose();for(const m of ms)m.dispose();}
export async function probeTemplate139(){const tools=await repairTools139(),probe=tools.meter,used=new Set(probe.children.map(o=>o.material));for(const[k,g]of Object.entries(tools)){if(k==='meter')continue;g.traverse(o=>{o.geometry?.dispose();if(o.material&&!used.has(o.material))o.material.dispose();});}return probe;}
export function fitProbe139(target,template,colour='red',bench=false){for(const o of [...target.children]){o.removeFromParent();o.traverse(q=>q.geometry?.dispose());}const model=template.clone(true);model.visible=true;model.traverse(o=>{if(o.geometry)o.geometry=o.geometry.clone();if(o.material){o.material=o.material.clone();if(/Polimero rojo/.test(o.material.name))o.material.color.set(colour==='black'?'#22282b':'#a83125');}});if(bench){model.rotation.z=Math.PI;model.position.y=-.004;target.userData.tip139=[0,-.185,0];}else{model.rotation.x=-Math.PI/2;model.position.z=.181;target.userData.tip139=[0,0,0];target.userData.grip118=[0,0,.115];}target.add(model);target.userData.nativeTool139=true;}
